import { type } from 'arktype';

export const migrationEntrySchema = type({
  name: 'string',
  hash: 'string',
  fromContract: 'string | null',
  toContract: 'string',
  operationCount: 'number',
  createdAt: 'string',
  refs: 'string[]',
  providedInvariants: 'string[]',
