import type { CoreSchemaView, SchemaTreeNode } from '@internal/framework-components/control';
import { ifDefined } from '@internal/utils/defined';
import type { Block, Presentations, Span, TreeNode } from '@prisma/cli-engine';
import { notOk, ok } from '@prisma/cli-engine/protocol';
import { createControlClient } from '../../control-api/client';
import type { CreateControlClient } from '../../control-api/types';
import {
  CliStructuredError,
  errorDatabaseConnectionRequired,
  errorDriverRequired,
  errorUnexpected,
} from '../../utils/cli-errors';
import { closeQuietly, maskConnectionUrl, sanitizeErrorMessage } from '../../utils/command-helpers';
import { ormConfigSection } from '../config-section';
import { defineOrmCommand } from '../define-command';
import { dbFlag } from '../flags';
import { normalizeError } from '../normalize-error';
import { controlProgressReporter } from '../progress';

interface SchemaDocument {
  readonly ok: true;
  readonly summary: string;
  readonly target: { readonly familyId: string; readonly id: string };
  readonly schema: unknown;
  readonly meta: { readonly dbUrl?: string };
  readonly timings: { readonly total: number };
}

const SUMMARY = 'Schema read successfully';

/**
 * A leading keyword and the name it introduces: `<keyword> <name>`, or
 * `<keyword>: <name>`. The keyword recedes and the name is the identifier.
 */
function keywordThenName(label: string): readonly Span[] | undefined {
  const colon = label.match(/^(.+?):\s*(\S.*)$/);
  if (colon?.[1] !== undefined && colon[2] !== undefined) {
    return [
      { text: colon[1], tone: 'muted' },
      { text: ': ' },
      { text: colon[2], tone: 'identifier' },
    ];
  }
  const spaced = label.match(/^(\S.*\S|\S+)\s+(\S+)$/);
  if (spaced?.[1] !== undefined && spaced[2] !== undefined) {
    return [
      { text: spaced[1], tone: 'muted' },
      { text: ' ' },
      { text: spaced[2], tone: 'identifier' },
    ];
  }
  return undefined;
}

/** `<name>: <detail> (<qualifier>)` — the name leads and the qualifier recedes. */
function namedDetail(label: string): readonly Span[] | undefined {
  const parts = label.match(/^([^:]+):\s*(.+)$/);
  if (parts?.[1] === undefined || parts[2] === undefined) {
    return undefined;
  }
  const [, name, rest] = parts;
  const qualified = rest.match(/^([^\s(]+)\s*(\([^)]+\))$/);
  if (qualified?.[1] !== undefined && qualified[2] !== undefined) {
    return [
      { text: name, tone: 'identifier' },
      { text: `: ${qualified[1]} ` },
      { text: qualified[2], tone: 'muted' },
    ];
  }
  return [{ text: name, tone: 'identifier' }, { text: `: ${rest}` }];
}

/** `<name> <rest>` — the name leads and the prose behind it recedes. */
function nameThenProse(label: string): readonly Span[] | undefined {
  const parts = label.match(/^(\S+)\s+(\S.*)$/);
  if (parts?.[1] === undefined || parts[2] === undefined) {
    return undefined;
  }
  return [{ text: parts[1], tone: 'identifier' }, { text: ' ' }, { text: parts[2], tone: 'muted' }];
}

/**
 * What a schema node's label means, said in tones.
 *
 * The families phrase these labels themselves, so the shapes recognised here
 * are positional (`<keyword> <name>`, `<name>: <detail>`) rather than a list of
 * words: a family that renames a keyword keeps its colouring, and no family's
 * vocabulary is written down in the framework layer.
 */
function labelSpans(node: SchemaTreeNode): readonly Span[] {
  switch (node.kind) {
    case 'root':
      return [{ text: node.label, tone: 'emphasis' }];
    case 'collection':
      return [{ text: node.label, tone: 'muted' }];
    case 'entity':
    case 'index':
      return keywordThenName(node.label) ?? [{ text: node.label, tone: 'identifier' }];
    case 'field':
      return namedDetail(node.label) ?? [{ text: node.label }];
    case 'dependency':
      return nameThenProse(node.label) ?? [{ text: node.label, tone: 'identifier' }];
    default:
      return [{ text: node.label }];
  }
}

function treeNode(node: SchemaTreeNode): TreeNode {
  return {
    label: labelSpans(node),
    ...ifDefined(
      'children',
      node.children === undefined || node.children.length === 0
        ? undefined
        : node.children.map(treeNode),
    ),
  };
}

function schemaPresentations(inputs: {
  readonly document: SchemaDocument;
  readonly schemaView: CoreSchemaView | undefined;
  readonly database: string | undefined;
}): Presentations {
  const { document, schemaView, database } = inputs;
  return {
    stdout: () => [],
    next: () => [],
    human: (): readonly Block[] => [
      ...(database === undefined
        ? []
        : [
            {
              kind: 'fields' as const,
              rail: true,
              rows: [{ label: 'database', value: database }],
            },
          ]),
      schemaView === undefined
        ? { kind: 'summary', status: 'ok', text: document.summary }
        : { kind: 'tree', roots: [treeNode(schemaView.root)] },
    ],
    json: () => document,
  };
}

export function createDbSchemaCommand(createClient: CreateControlClient) {
  return defineOrmCommand({
    help: {
      summary: 'Inspect the live database schema',
      description:
        'Reads the live database schema and prints it as a tree, or as the result\n' +
        'document with --json. Always read-only: it never writes a file and never\n' +
        'changes the database.',
      examples: ['db schema', 'db schema --db $DATABASE_URL', 'db schema --json'],
    },
    args: { flags: { db: dbFlag } },
    needs: { config: ormConfigSection },
    handler: async (args, ctx) => {
      const startedAt = Date.now();
      const dbConnection = args.flags.db ?? ctx.config.db?.connection;
      if (dbConnection === undefined) {
        return notOk(
          normalizeError(
            errorDatabaseConnectionRequired({
              why: 'Database connection is required for db schema (set db.connection in prisma.config.ts, or pass --db <url>)',
              commandName: 'db schema',
              missingFlags: ['--db'],
            }),
          ),
        );
      }
      if (ctx.config.driver === undefined) {
        return notOk(
          normalizeError(errorDriverRequired({ why: 'Config.driver is required for db schema' })),
        );
      }

      const client = createClient({
        family: ctx.config.family,
        target: ctx.config.target,
        adapter: ctx.config.adapter,
        driver: ctx.config.driver,
        extensions: ctx.config.extensions ?? [],
      });

      let schema: unknown;
      let schemaView: CoreSchemaView | undefined;
      try {
        schema = await client.introspect({
          connection: dbConnection,
          onProgress: controlProgressReporter(ctx.report),
        });
        schemaView = client.toSchemaView(schema);
      } catch (error) {
        if (CliStructuredError.is(error)) {
          return notOk(normalizeError(error));
        }
        const safeMessage = sanitizeErrorMessage(
          error instanceof Error ? error.message : String(error),
          typeof dbConnection === 'string' ? dbConnection : undefined,
        );
        return notOk(
          normalizeError(
            errorUnexpected(safeMessage, {
              why: `Unexpected error during db schema: ${safeMessage}`,
            }),
          ),
        );
      } finally {
        await closeQuietly(client);
      }

      const database =
        typeof dbConnection === 'string' ? maskConnectionUrl(dbConnection) : undefined;
      const document: SchemaDocument = {
        ok: true,
        summary: SUMMARY,
        target: { familyId: ctx.config.family.familyId, id: ctx.config.target.targetId },
        schema,
        meta: { ...ifDefined('dbUrl', database) },
        timings: { total: Date.now() - startedAt },
      };

      return ok(
        ctx.present({ data: document }, schemaPresentations({ document, schemaView, database })),
      );
    },
  });
}

export const dbSchemaCommand = createDbSchemaCommand(createControlClient);

#!/usr/bin/env python3
"""
Resolve the output schema for a dbt model.

Usage:
    python3 resolve_dbt_schema.py <dbt_project_yml_path> <model_sql_path>

Returns the resolved schema name (uppercase), e.g., "PROD", "PROD_STAGE", "PROD_LINEAGE"
"""

import argparse
import re
import sys
from pathlib import Path


def safe_user_path(path_value, base_dir="."):
    """Resolve a CLI path under the current workspace."""
    if base_dir != ".":
        raise ValueError("Custom base directories are not supported for CLI paths")
    base_path = Path.cwd().resolve()
    resolved_path = Path(path_value).expanduser().resolve()
    try:
        resolved_path.relative_to(base_path)
    except ValueError as exc:
        raise ValueError(f"Path escapes allowed directory: {path_value}") from exc
    return resolved_path
from typing import Dict, List, Optional, Tuple, Union

import yaml


def parse_model_config_schema(model_content: str) -> Optional[str]:
    """Extract schema from model's config block."""
    pattern = r"\{\{\s*config\s*\([^)]*\bschema\s*=\s*['\"]([^'\"]+)['\"][^)]*\)\s*\}\}"
    match = re.search(pattern, model_content, re.IGNORECASE | re.DOTALL)
    if match:
        return match.group(1).upper()

    snapshot_pattern = r"target_schema\s*=\s*generate_schema_name\s*\(\s*['\"]([^'\"]+)['\"]"
    match = re.search(snapshot_pattern, model_content, re.IGNORECASE | re.DOTALL)
    if match:
        return match.group(1).upper()

    return None


def parse_dbt_project_routing(
    dbt_project: dict, project_name: str
) -> Tuple[Dict[str, str], Dict[str, str]]:
    """Extract schema and database routing rules from dbt_project.yml."""
    schema_routing = {}  # type: Dict[str, str]
    database_routing = {}  # type: Dict[str, str]

    models_config = dbt_project.get("models", {})
    project_config = models_config.get(project_name, {})

    def extract_routing(config: dict, current_path: str = "") -> None:
        for key, value in config.items():
            if key.startswith("+"):
                continue
            if not isinstance(value, dict):
                continue
            new_path = f"{current_path}/{key}" if current_path else key
            schema = value.get("schema") or value.get("+schema")
            if schema:
                if "{{" not in schema:
                    schema_routing[new_path] = schema.upper()
            database = value.get("database") or value.get("+database")
            if database:
                if "{{" not in database:
                    database_routing[new_path] = database.upper()
            extract_routing(value, new_path)

    extract_routing(project_config)
    return schema_routing, database_routing


def parse_dbt_project_schema_routing(dbt_project: dict, project_name: str) -> Dict[str, str]:
    schema_routing, _ = parse_dbt_project_routing(dbt_project, project_name)
    return schema_routing


def get_model_relative_path(dbt_project_path: Path, model_path: Path) -> str:
    dbt_project_dir = dbt_project_path.parent
    model_relative = model_path.relative_to(dbt_project_dir)
    parts = model_relative.parts
    if parts and parts[0] == "models":
        return str(Path(*parts[1:]))
    return str(model_relative)


def find_matching_schema(
    model_relative_path: str, routing: Dict[str, str]
) -> Optional[str]:
    model_dir = str(Path(model_relative_path).parent)
    matches = []  # type: List[Tuple[str, str]]
    for route_path, schema in routing.items():
        if model_dir == route_path or model_dir.startswith(route_path + "/"):
            matches.append((route_path, schema))
    if not matches:
        return None
    matches.sort(key=lambda x: len(x[0]), reverse=True)
    return matches[0][1]


def apply_schema_prefix(schema: str, target_schema: str = "PROD") -> str:
    if not schema or schema.upper() == target_schema.upper():
        return target_schema.upper()
    return f"{target_schema.upper()}_{schema.upper()}"


def resolve_schema(
    dbt_project_path: Union[str, Path],
    model_path: Union[str, Path],
    default_schema: str = "PROD",
    apply_prefix: bool = True,
) -> str:
    dbt_project_path = Path(dbt_project_path)
    model_path = Path(model_path)

    model_content = model_path.read_text()

    config_schema = parse_model_config_schema(model_content)
    if config_schema:
        if apply_prefix:
            return apply_schema_prefix(config_schema, default_schema)
        return config_schema

    with open(dbt_project_path) as f:
        dbt_project = yaml.safe_load(f)

    project_name = dbt_project.get("name", "")

    routing = parse_dbt_project_schema_routing(dbt_project, project_name)
    model_relative = get_model_relative_path(dbt_project_path, model_path)
    matched_schema = find_matching_schema(model_relative, routing)
    if matched_schema:
        if apply_prefix:
            return apply_schema_prefix(matched_schema, default_schema)
        return matched_schema

    return default_schema.upper()


def main() -> None:
    parser = argparse.ArgumentParser(
        description="Resolve the output schema for a dbt model"
    )
    parser.add_argument("dbt_project_path", help="Path to dbt_project.yml")
    parser.add_argument("model_path", help="Path to the model SQL file")
    parser.add_argument("--default", default="PROD", help="Default schema (default: PROD)")
    parser.add_argument("--no-prefix", action="store_true", help="Don't apply PROD_ prefix")

    args = parser.parse_args()

    dbt_project_path = safe_user_path(args.dbt_project_path)
    model_path = safe_user_path(args.model_path)

    if not dbt_project_path.exists():
        print(f"Error: dbt_project.yml not found: {dbt_project_path}", file=sys.stderr)
        sys.exit(1)

    if not model_path.exists():
        print(f"Error: Model file not found: {model_path}", file=sys.stderr)
        sys.exit(1)

    apply_prefix = not args.no_prefix
    schema = resolve_schema(dbt_project_path, model_path, args.default, apply_prefix)
    print(schema)


if __name__ == "__main__":
    main()

